csySummerTimeRecurringStart = MibScalar((1, 3, 6, 1, 4, 1, 9, 9, 131, 1, 3, 3), OctetString().subtype(subtypeSpec=ValueSizeConstraint(6, 6)).setFixedLength(6)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: csySummerTimeRecurringStart.setStatus('current')
if mibBuilder.loadTexts: csySummerTimeRecurringStart.setDescription('Indicates summertime starts at this time every year.\n        octets    contents     range\n        1         week        1..5,ff last = ff \n        2-3       day         1..7 \n                              where sunday = 1 saturday = 7\n        4         month       1..12 \n                              where january = 1 december = 12\n        5         hour        0..23\n        6         min         0..59\n        For example, the first Monday in Feb at 13:30pm  \n        should be given as\n            01 00 02 02 0e 1e  \n        For the last Tuesday in dec at 1:20am should be\n        given as\n           ff 00 03 0c 01 14 \n        This object is not instantiated when \n        csySummerTimeStatus object is set to false.')
csySummerTimeRecurringEnd = MibScalar((1, 3, 6, 1, 4, 1, 9, 9, 131, 1, 3, 4), OctetString().subtype(subtypeSpec=ValueSizeConstraint(6, 6)).setFixedLength(6)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: csySummerTimeRecurringEnd.setStatus('current')
if mibBuilder.loadTexts: csySummerTimeRecurringEnd.setDescription('Indicates summertime ends at this time every year.\n        octets    contents      range\n        1         week        1..5,ff where ff = last \n        2-3       day         1..7 \n                              where sunday = 1 saturday = 7\n        4         month       1..12 \n                              where january = 1 december = 12\n        5         hour        0..23\n        6         min         0..59\n        For example, the third friday in February at 3:30am \n        should be given as\n             03 00 06 02 03 1e\n\n        For the first Tuesday in May at 1:20am  should \n        be given as\n            01 00 03 05 01 14\n        This object is not instantiated when \n        csySummerTimeStatus object is set to false.')
